-- ====== 3. 确保 issue_date 不为空(用 create_time 填充) ======
UPDATE certificate SET issue_date = DATE(create_time) WHERE issue_date IS NULL;

-- ====== 4. 验证结果 ======
SELECT '=== 证书颁发日期统计(修复后) ===' AS info;
SELECT 
  cert_type,
  COUNT(*) AS total,
  SUM(CASE WHEN issue_date IS NULL THEN 1 ELSE 0 END) AS null_count,
  MIN(issue_date) AS earliest,
  MAX(issue_date) AS latest
FROM certificate
GROUP BY cert_type
ORDER BY total DESC;

SELECT '=== 模板字段配置(birthday/issueDate) ===' AS info;
SELECT t.name AS template_name, ct.field_key, ct.x, ct.y
FROM certificate_template_field ct
JOIN certificate_template t ON ct.template_id = t.id
WHERE ct.field_key IN ('birthday', 'issueDate')
ORDER BY t.name, ct.field_key;
